INSERT INTO menu_items (id, category_id, name, description, price, unit, heat, fusion, tags, position) VALUES ('ackee-saltfish-tostones', 'appetizers', '{"en":"Ackee & saltfish tostones","es":"Tostones con ackee y bacalao","fr":"Tostones ackee & morue","de":"Tostones mit Ackee & Stockfisch"}', '{"en":"Jamaica’s national dish on crisp green-plantain tostones.","es":"El plato nacional de Jamaica sobre tostones crujientes.","fr":"Le plat national jamaïcain sur des tostones croustillants.","de":"Jamaikas Nationalgericht auf knusprigen Tostones."}', 48500, 'each', 1, -1, '["signature","seafood"]', 0);
