INSERT INTO menu_items (id, category_id, name, description, price, unit, heat, fusion, tags, position) VALUES ('calamari', 'appetizers', '{"en":"Calamari","es":"Calamares","fr":"Calamars","de":"Calamari"}', '{"en":"Crispy fried calamari with tartar sauce.","es":"Calamares fritos crujientes con salsa tártara.","fr":"Calamars frits croustillants, sauce tartare.","de":"Knusprig frittierte Calamari mit Remoulade."}', 55000, 'each', 0, 0, '["seafood"]', 8);
