INSERT INTO menu_items (id, category_id, name, description, price, unit, heat, fusion, tags, position) VALUES ('rasta-pasta', 'rasta-pasta', '{"en":"Rasta Pasta"}', '{"en":"Penne in creamy Alfredo with bell peppers, onion and parmesan. Guests’ favourite: oxtail.","es":"Penne en salsa Alfredo con pimientos, cebolla y parmesano. La favorita: rabo de res.","fr":"Penne sauce Alfredo, poivrons, oignon et parmesan. La préférée : queue de bœuf.","de":"Penne in Alfredosoße mit Paprika, Zwiebel und Parmesan. Gästeliebling: Ochsenschwanz."}', 0, 'each', 1, -1, '["signature","first-timer"]', 10);
