INSERT INTO menu_items (id, category_id, name, description, price, unit, heat, fusion, tags, position) VALUES ('curried-goat', 'specialties', '{"en":"Curried goat","es":"Chivo al curry","fr":"Cabri au curry","de":"Ziegencurry"}', '{"en":"Slow-cooked in Jamaican curry with green seasoning and hot pepper. With a side of your choice.","es":"Cocido lento en curry jamaiquino con sazón verde y ají picante. Con acompañante a elegir.","fr":"Mijoté au curry jamaïcain, assaisonnement vert et piment. Avec un accompagnement au choix.","de":"Langsam gegart in jamaikanischem Curry mit grüner Würze und Chili. Mit Beilage nach Wahl."}', 159500, 'each', 3, -2, '[]', 12);
INSERT INTO menu_items (id, category_id, name, description, price, unit, heat, fusion, tags, position) VALUES ('braised-oxtail', 'specialties', '{"en":"Braised oxtail","es":"Rabo de res guisado","fr":"Queue de bœuf braisée","de":"Geschmorter Ochsenschwanz"}', '{"en":"Braised oxtail with beans, onion, peppers and pimento — the one Punta Cana talks about. With a side of your choice.","es":"Rabo de res guisado con habichuelas, cebolla, pimientos y pimienta de Jamaica — del que habla Punta Cana. Con acompañante a elegir.","fr":"Queue de bœuf braisée, haricots, oignon, poivrons et piment de la Jamaïque — celle dont parle Punta Cana. Avec un accompagnement au choix.","de":"Geschmorter Ochsenschwanz mit Bohnen, Zwiebel, Paprika und Piment — der, von dem Punta Cana spricht. Mit Beilage nach Wahl."}', 179900, 'each', 1, -2, '["signature","first-timer"]', 13);
INSERT INTO menu_items (id, category_id, name, description, price, unit, heat, fusion, tags, position) VALUES ('fajitas', 'specialties', '{"en":"Fajitas"}', '{"en":"Sizzling peppers and onion with flour tortillas, cheese, sour cream, beans and guacamole.","es":"Pimientos y cebolla a la plancha con tortillas de harina, queso, crema agria, frijoles y guacamole.","fr":"Poivrons et oignons grésillants, tortillas de blé, fromage, crème aigre, haricots et guacamole.","de":"Brutzelnde Paprika und Zwiebeln mit Weizentortillas, Käse, Sauerrahm, Bohnen und Guacamole."}', 0, 'each', 1, 2, '["vegetarian-option"]', 14);
