INSERT INTO specials (id, title, body, days, start_time, end_time, price, cta, item_ids, flyer, position) VALUES ('rum-reggae', '{"en":"Rum & Reggae Sunday","es":"Domingo de ron y reggae","fr":"Dimanche rhum & reggae","de":"Rum & Reggae Sonntag"}', '{"en":"Reggae on the sound system, karaoke and half-off rum punch.","es":"Reggae en el sound system, karaoke y rum punch a mitad de precio.","fr":"Reggae sur le sound system, karaoké et punch au rhum à moitié prix.","de":"Reggae vom Soundsystem, Karaoke und Rum Punch zum halben Preis."}', '[0]', '18:00', '22:00', 35000, 'book', '[]', '{"bg":"jungle","ink":"gold","sticker":"One Love"}', 6);
INSERT INTO seasons (slug, name, starts_on, ends_on, priority, published, tokens, hero, blocks) VALUES ('dia-de-muertos', '{"en":"Día de Muertos","es":"Día de Muertos","fr":"Día de Muertos","de":"Día de Muertos"}', '2026-10-24', '2026-11-03', 10, 1, '{"--c-gold":"#f59f0b","--c-hibiscus":"#e8287f","--c-mezcal":"#5b2a86","--c-cream":"#fff3df"}', '{"kicker":{"en":"New rotation","es":"Nueva rotación","fr":"Nouvelle rotation","de":"Neue Rotation"},"headline":{"en":"Half calavera. Whole heart.","es":"Media calavera. Corazón entero.","fr":"Mi-calavera. Tout le cœur.","de":"Halb Calavera. Ganzes Herz."},"body":{"en":"Marigolds on the terrace, candles on the bar and the sound system playing for the ones we remember. 1–2 November.","es":"Cempasúchil en la terraza, velas en la barra y el sound system tocando por los que recordamos. 1–2 de noviembre.","fr":"Des œillets d’Inde sur la terrasse, des bougies au bar et le sound system pour ceux dont on se souvient. 1–2 novembre.","de":"Tagetes auf der Terrasse, Kerzen an der Bar und das Soundsystem für die, an die wir denken. 1.–2. November."},"cta":"book"}', '[{"type":"story","title":{"en":"Remember them loud","es":"Recordarlos a todo volumen","fr":"Se souvenir en musique","de":"Laut erinnern"},"body":{"en":"In Mexico the dead come home for two nights, and the living cook their favourite dishes. Bring a photo for the ofrenda by the DJ booth — we light a candle for every one.","es":"En México los muertos vuelven a casa dos noches y los vivos cocinan sus platos favoritos. Trae una foto para la ofrenda junto a la cabina del DJ — encendemos una vela por cada una.","fr":"Au Mexique, les morts rentrent à la maison deux nuits, et les vivants cuisinent leurs plats préférés. Apporte une photo pour l’ofrenda près de la cabine du DJ — on allume une bougie pour chacune.","de":"In Mexiko kommen die Toten für zwei Nächte nach Hause, und die Lebenden kochen ihre Lieblingsgerichte. Bring ein Foto für die Ofrenda am DJ-Pult mit — für jedes zünden wir eine Kerze an."}},{"type":"dishes","title":{"en":"On the menu this season","es":"En el menú esta temporada","fr":"Au menu cette saison","de":"Diese Saison auf der Karte"},"itemIds":["quesabirria","braised-oxtail","jerk-pork-taco","vanilla-flan"]}]');
INSERT INTO seasons (slug, name, starts_on, ends_on, priority, published, tokens, hero, blocks) VALUES ('navidad-caribena', '{"en":"Caribbean Christmas","es":"Navidad Caribeña","fr":"Noël caribéen","de":"Karibische Weihnacht"}', '2026-12-01', '2027-01-06', 5, 0, '{"--c-hibiscus":"#d7263d","--c-jungle":"#1f7a3a","--c-gold":"#f2c14e"}', '{"kicker":{"en":"Holiday rotation","es":"Rotación navideña","fr":"Rotation des fêtes","de":"Festtags-Rotation"},"headline":{"en":"Sorrel season is here.","es":"Llegó la temporada de sorrel.","fr":"C’est la saison du sorrel.","de":"Sorrel-Saison ist da."},"body":{"en":"Jamaican sorrel, Mexican ponche and a Christmas line-up on the sound system.","es":"Sorrel jamaiquino, ponche mexicano y una programación navideña en el sound system.","fr":"Sorrel jamaïcain, ponche mexicain et une programmation de Noël sur le sound system.","de":"Jamaikanischer Sorrel, mexikanischer Ponche und ein Weihnachts-Line-up vom Soundsystem."},"cta":"book"}', '[{"type":"story","title":{"en":"Same flower, two Christmases","es":"La misma flor, dos Navidades","fr":"Même fleur, deux Noëls","de":"Eine Blüte, zwei Weihnachten"},"body":{"en":"Jamaica drinks sorrel at Christmas; Mexico calls the same hibiscus jamaica. We pour both — and the company Christmas party is on us to plan.","es":"Jamaica toma sorrel en Navidad; México llama jamaica a la misma flor. Servimos las dos — y la fiesta de Navidad de tu empresa la organizamos nosotros.","fr":"La Jamaïque boit du sorrel à Noël ; le Mexique appelle jamaica le même hibiscus. On sert les deux — et on organise ta fête de fin d’année.","de":"Jamaika trinkt zu Weihnachten Sorrel, Mexiko nennt denselben Hibiskus Jamaica. Wir schenken beides aus — und planen eure Firmen-Weihnachtsfeier."}},{"type":"dishes","title":{"en":"On the menu this season","es":"En el menú esta temporada","fr":"Au menu cette saison","de":"Diese Saison auf der Karte"},"itemIds":["curried-goat","braised-oxtail","jamaican-bread-pudding"]}]');
